UPDATE campus_report_job
job_name = #{jobName}, report_type = #{reportType}, template_id = #{templateId}, period_rule = #{periodRule}, schedule_cron = #{scheduleCron}, output_format = #{outputFormat}, job_status = #{jobStatus}, last_run_time = #{lastRunTime}, next_run_time = #{nextRunTime}, reviewer_user_id = #{reviewerUserId}, description = #{description}, update_user_id = #{updateUserId}
